from pathlib import Path
exec(Path('tools/v100_patch_v2.py').read_text(), {'__name__':'__main__'})

p=Path('smart-fuwa-memory.js'); s=p.read_text()
old='''function voiceStart(){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition,status=document.getElementById("fuwaVoiceStatus"),btn=document.getElementById("fuwaVoiceButton"),area=document.getElementById("fuwaQuickDump");if(!Speech){if(status)status.textContent="Voice transcription isn’t available in this iPhone/browser build. You can still type or use iOS dictation in the text box.";area?.focus();return}if(voiceActive){voiceRecognition?.stop?.();return}const rec=new Speech();voiceRecognition=rec;rec.continuous=true;rec.interimResults=true;rec.lang=document.documentElement.lang||"en-US";let finalText="";rec.onstart=()=>{voiceActive=true;if(btn)btn.textContent="■ Stop voice";if(status)status.textContent="Listening… audio is not saved by Fuwa."};rec.onresult=e=>{let interim="";for(let i=e.resultIndex;i<e.results.length;i++){const t=e.results[i][0].transcript;if(e.results[i].isFinal)finalText+=t+" ";else interim+=t}if(area){const base=area.dataset.voiceBase||area.value;area.dataset.voiceBase=base;area.value=(base+(base&&finalText?" ":"")+finalText+interim).trimStart()}};rec.onerror=()=>{if(status)status.textContent="Voice transcription stopped. Your existing text is still here."};rec.onend=()=>{voiceActive=false;if(btn)btn.textContent="◉ Voice journal";if(area){area.dataset.voiceBase=area.value}if(status)status.textContent="Voice stopped. Review the text before saving anything."};rec.start()}'''
new='''function voiceStart(){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition,status=document.getElementById("fuwaVoiceStatus"),btn=document.getElementById("fuwaVoiceButton"),area=document.getElementById("fuwaQuickDump");if(status)status.textContent="Preparing voice journaling…";if(!Speech){if(status)status.textContent="Voice transcription isn’t available in this iPhone/browser build. You can still type or use iOS dictation in the text box.";area?.focus();return}if(voiceActive){voiceRecognition?.stop?.();return}let rec=null;try{rec=new Speech()}catch(_){if(status)status.textContent="Voice transcription isn’t available right now. Your text is safe — you can keep typing or use iOS dictation.";area?.focus();return}voiceRecognition=rec;rec.continuous=true;rec.interimResults=true;rec.lang=document.documentElement.lang||"en-US";let finalText="";rec.onstart=()=>{voiceActive=true;if(btn)btn.textContent="■ Stop voice";if(status)status.textContent="Listening… Fuwa does not save an audio recording."};rec.onresult=e=>{let interim="";for(let i=e.resultIndex;i<e.results.length;i++){const t=e.results[i][0].transcript;if(e.results[i].isFinal)finalText+=t+" ";else interim+=t}if(area){const base=area.dataset.voiceBase||area.value;area.dataset.voiceBase=base;area.value=(base+(base&&finalText?" ":"")+finalText+interim).trimStart()}};rec.onerror=()=>{voiceActive=false;if(btn)btn.textContent="◉ Voice journal";if(status)status.textContent="Voice transcription stopped. Your existing text is still here."};rec.onend=()=>{voiceActive=false;if(btn)btn.textContent="◉ Voice journal";if(area){area.dataset.voiceBase=area.value}if(status)status.textContent="Voice stopped. Review the text before saving anything."};try{rec.start()}catch(_){voiceActive=false;if(btn)btn.textContent="◉ Voice journal";if(status)status.textContent="Voice transcription couldn’t start. Your text is safe — you can keep typing or use iOS dictation.";area?.focus()}}'''
assert old in s
p.write_text(s.replace(old,new,1))
